/* 听友（tingyou.fm）· 融合版（2026-11-14）
 * 硬规矩（真机踩到）：**表达式里不能发请求、不能读写状态** —— 所以 let/字段表达式里绝不调 http/vars；
 * 探测线路、记忆线路一律放脚本（阶段脚本 / vars.optionsScript / actions）。
 */
var TY_LINES = ["https://appp.fdhtbz.cn/api", "https://api-preview.toulaopao.cc/api", "https://laopaoaappi.oobyvy.vip/api", "https://ffggewvge.dasfrvvbbahhafdgserqw.cc/api"];
var TY_UA = 'Mozilla/5.0 (Linux; Android 12; Pixel 5) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120 Mobile Safari/537.36';

/* —— 以下是「纯函数」：只做字符串处理，表达式里可以安全调用 —— */
function tyLineOf(s) {
  s = String(s || '');
  var m = s.match(/https?:\/\/[^\s)]+/);
  if (m) { return m[0]; }
  return TY_LINES[0];
}
/* —— 以下要发请求/写状态：只在脚本里调 —— */
function tyHd(extra) {
  var h = { 'Accept': 'application/json, text/plain, */*', 'Origin': 'https://www.tingyou.fm',
            'Referer': 'https://www.tingyou.fm/', 'User-Agent': TY_UA };
  if (extra) { for (var k in extra) { h[k] = extra[k]; } }
  return h;
}
function tyProbe(base) {
  var t0 = Date.now();
  try {
    var r = http.get(base + '/h5/listening/rank?section=hot&page=1', { headers: tyHd(), timeout: 5000 });
    return { ok: !!(r && r.ok && r.status === 200), ms: Date.now() - t0 };
  } catch (e) { return { ok: false, ms: Date.now() - t0 }; }
}
/* 选项脚本：测所有线路 → 可用的排前面（返回选项名数组） */
function tyLineOptions() {
  var items = [], i;
  for (i = 0; i < TY_LINES.length; i++) {
    var r = tyProbe(TY_LINES[i]);
    items.push({ u: TY_LINES[i], ok: r.ok, ms: r.ms });
  }
  items.sort(function (a, b) { return (a.ok ? a.ms : 999999) - (b.ok ? b.ms : 999999); });
  var out = [];
  for (i = 0; i < items.length; i++) { out.push(items[i].u); }
  return out;
}
/* 动作：测线路并把最快可用的写进设置 */
function tyAutoLine() {
  var items = [], i;
  for (i = 0; i < TY_LINES.length; i++) {
    var r = tyProbe(TY_LINES[i]);
    items.push({ u: TY_LINES[i], ok: r.ok, ms: r.ms });
  }
  items.sort(function (a, b) { return (a.ok ? a.ms : 999999) - (b.ok ? b.ms : 999999); });
  var out = [];
  for (i = 0; i < items.length; i++) { out.push((items[i].ok ? '✅ ' : '❌ ') + items[i].u + '  ' + items[i].ms + 'ms'); }
  var best = items[0];
  if (best && best.ok) { try { vars.set('api', best.u); } catch (e) {} out.push('', '已设为：' + best.u); }
  else { out.push('', '⚠️ 没有可用线路，先别改设置'); }
  return out;
}
/* 音频出口：默认不改写 */
function tyAudio(u) {
  var s = String(u || '');
  var v = String(vars.audio || '');   // 表达式里读变量只能用 vars.X（属性）；vars.get() 属读状态，会被引擎拒
  var m = v.match(/^([a-z0-9.\-]+)$/);
  if (m && s.indexOf('file.') >= 0) { return replaceText(s, 'file.hgeuz.cn', m[1]); }
  return s;
}
function tyAid(u) { var m = String(u || '').match(/album\/([0-9]+)/); return m ? m[1] : ''; }
function tyUrlAid(u) { var m = String(u || '').match(/\/p\/([0-9]+)\//); return m ? m[1] : ''; }
function tyUrlIdx(u) { var m = String(u || '').match(/\/p\/\d+\/([0-9]+)/); return m ? m[1] : ''; }
